+const FOLLOW05 = flag05('realride05') || flag05('follow05');
 const M06_LA = (() => {
   const v = typeof location !== 'undefined' ? Number(new URLSearchParams(location.search).get('m06la')) : NaN;
   return Number.isFinite(v) && v > 5 ? v : 40;
