     const fb = this.course.sample(Math.max(0, s - p.back * 0.5)); // smoothing of heading
     const dir = f.tan.clone().lerp(fb.tan, 0.35).normalize();
     let up = f.up.clone();
+    // Blend out still-image camera alignment over Screen 05 for diagnostic A/B tests.
