  if (!(c.h > 0)) c.kind = Math.abs(cl) >= 0.1 ? 'lane' : 'water'; };
const coinWarn = [];
if (!q.get('layoutcoins')) {
  PAINTED.forEach(([cs, cl], i) => { const [sp, lp] = toPath(cs, cl); placeCoin(coins[i], sp, lp); if (Math.abs(lp) > 0.33) coinWarn.push({ i, s: sp, lat: lp }); });
  RUN2.forEach(([cs, cl], i) => placeCoin(coins[8 + i], cs, cl));
