}
PATH.info.coinsOutOfLanes = coinWarn;
{ const L0 = window.coinLayout(); window.coinLayout = () => coins.map((c, i) => ({ s: c.s, lat: +c.lat.toFixed(3), h: c.h, run: L0[i]?.run, runKind: L0[i]?.runKind, p: c.p0.toArray().map((x) => +x.toFixed(4)), n: c.n0.toArray().map((x) => +x.toFixed(4)) })); }
