      "const ownOf = (kind, atlas, k) => { const r = PH.own?.[kind]?.rows?.[k]; return r && !q.get('noown') && ringT(k) < OWNFADE[1] ? { tex: atlas, vr: [r[0] / PH.own[kind].h, r[1] / PH.own[kind].h] } : null; };")
