    const lim = wide ? SC.tunnel.approach.radius - 0.15 : HWD - 0.04, nr = wide ? 5 : (HWD - Math.abs(e37) > 0.14 ? 3 : 2);
    for (let r = 0; r < nr; r++) { const w = (0.12 + rp() * 0.09) * (r ? 0.85 : 1), lat = THREE.MathUtils.clamp(e37 + side * (0.03 + r * 0.075 + rp() * 0.03), -lim, lim);
