// real finger taps on the Bubble Blast / Turbo Spin buttons (CDP touch at the button centre) + a swipe right after: buttons work, swipes unaffected
const { chromium } = require('playwright'); const { spawn } = require('child_process');
(async () => { const port = 9577; const srv = spawn('python3', ['-m', 'http.server', '--bind', '127.0.0.1', String(port)], { cwd: process.argv[2], stdio: 'ignore' }); await new Promise((r) => setTimeout(r, 1200));
  const b = await chromium.launch({ args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] }); const ctx = await b.newContext({ viewport: { width: 412, height: 915 }, isMobile: true, hasTouch: true }); const p = await ctx.newPage();
  await p.goto(`http://127.0.0.1:${port}/play3.html?w=412&h=915`); await p.waitForFunction(() => window.ready === true, null, { timeout: 900000 });
  const cdp = await ctx.newCDPSession(p); const tap = async (sel) => { const r = await p.evaluate((s) => { const e = document.querySelector(s).getBoundingClientRect(); return [e.x + e.width / 2, e.y + e.height / 2]; }, sel);
    await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: r[0], y: r[1], id: 2 }] }); await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] }); };
  let t = 0; const step = async (n) => { let o; for (let i = 0; i < n; i++) { o = await p.evaluate((tt) => window.step(tt, 1 / 30, 0, 2.2), t); t += 1 / 30; } return o; };
  await step(560);   // into the tunnel (s ~ 41: buttons shown there)
  const c0 = await step(1); await tap('#blast'); const c1 = await step(40); await tap('#turbo'); const t1 = await step(10); const t2 = await step(80);
  const lat0 = (await step(1)).lat; await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: 280, y: 560, id: 1 }] });
  for (let k = 1; k <= 4; k++) { await cdp.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: 280 - 30 * k, y: 563, id: 1 }] }); await step(1); }
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] }); const lat1 = (await step(12)).lat;
  console.log(JSON.stringify({ coins_before_blast: c0.coins, coins_after_blast: c1.coins, blast_active_during: c1.blast, turbo_value_right_after_tap: t1.turbo, s_gain_with_turbo: +(t2.s - t1.s).toFixed(2), s_expected_normal: +(80 * 2.2 / 30).toFixed(2), abilities_log: await p.evaluate(() => window.__abLog ?? null), swipe_after_buttons: { lat_before: lat0, lat_after: lat1 }, swipe_log: await p.evaluate(() => window.input.log.slice(-2)) }));
  await b.close(); srv.kill(); })();
EOF
NODE_PATH=$(npm root -g) timeout 1200 node abil.cjs sec/section 2>&1 | tail -2

